const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers;
const signatureHeader = headers['x-hub-signature-256'];


if (!signatureHeader) {
  throw new Error('Unauthorized: Missing X-Hub-Signature-256 header.');
}

const signature = signatureHeader.split('=')[1];
const APP_SECRET = $env.WHATSAPP_APP_SECRET;

// Extracting the available key from the binary
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error('Error: No binary raw body found. Make sure "Raw Body" option is enabled in Webhook node.');
}
const rawBodyBase64 = item.binary[binaryKeys[0]].data;

// Convert Base64 to a raw Buffer
const rawBodyBuffer = Buffer.from(rawBodyBase64, 'base64');

// Calculating the signature using the raw buffer
const expectedSignature = crypto
  .createHmac('sha256', APP_SECRET)
  .update(rawBodyBuffer)
  .digest('hex');

const signatureBuffer = Buffer.from(signature, 'hex');
const expectedBuffer = Buffer.from(expectedSignature, 'hex');

// Security comparison to prevent timing attacks
if (
  signatureBuffer.length !== expectedBuffer.length ||
  !crypto.timingSafeEqual(signatureBuffer, expectedBuffer)
) {
  throw new Error('Forbidden: Invalid Webhook Signature.');
}

// Parse the raw body and pass clean WhatsApp data
const parsedBody = JSON.parse(rawBodyBuffer.toString('utf8'));

return {
  json: parsedBody
};

