const response = $input.first().json;
const segments = response.segments || [];
const text = (response.text || "").trim();
const payload = $('JS Code - Extract WhatsApp Payload').first().json;

const db = $('PostgreSQL - UPSERT Lead').first().json;

// 1. التحقق من طول النص
if (text.length === 0) {
  return [{ json: { isClean: false, isNoisy: true, text: "", reason: "Empty text" } }];
}

// 2. فحص شرائح الصوت لمؤشرات الضوضاء والهلوسة والصمت
let isNoisyOrSilent = false;

if (segments.length > 0) {
  isNoisyOrSilent = segments.some(segment => {
    const highNoSpeech = segment.no_speech_prob > 0.6;
    const highCompression = segment.compression_ratio > 2.4; // تشير لتكرار الكلمات أو الهلوسة
    const lowLogProb = segment.avg_logprob < -1.0; // تشير لثقة ضعيفة جداً بالنص

    return highNoSpeech || highCompression || lowLogProb;
  });
}

const isClean = !isNoisyOrSilent;
const isNoisy = isNoisyOrSilent;

return [{
  json: {
    ...payload,
    ...db,
    isClean,
    isNoisy,
    text
  }
}];

