const items = $input.all();

return items.map(item => {
    const json = item.json;
    const rawMessage = $('PostgreSQL - UPSERT Text Messages').first().json.content || $('PostgreSQL - UPSERT Audio Messages').first().json.content || '';
    const cleanMessage = rawMessage.trim().toLowerCase();
    const phone = $('JS Code - Extract WhatsApp Payload').first().json.phone || json.from || '';
    const leadId = $('PostgreSQL - UPSERT Lead').first().json.lead_id || json.id || null;

    let route = 'AGENT';
    let staticResponse = null;
    let intent = 'GENERAL_QUERY';

    // 1. فحص رسائل الاحتيال والمسابقات والسبام (Scam / Prize Spam)
    const scamKeywords = ['كسبت', 'اربح', 'مسابقة', 'جائزة', 'مبروك فزت', 'سحب على', 'ربح اليوم', 'مبروك كسبت', 'ignore previous instructions', 'ignore all instructions', 'system prompt', 'you are now', 'تجاهل التعليمات', 'انسى التعليمات'];
    if (scamKeywords.some(kw => cleanMessage.includes(kw))) {
        route = 'STATIC';
        intent = 'ABUSE';
        staticResponse = "عذراً، هذا الحساب مخصص لخدمات الدعم والاستفسارات الرسمية فقط.";
    }

    // 3. فحص التحيات البسيطة (Greetings)
    else if (['مرحبا', 'مرحباً', 'هلا', 'مساء الخير', 'صباح الخير', 'اهلا', 'السلام عليكم', 'سلام عليكم', 'hi', 'hello', 'hey'].includes(cleanMessage)) {
        route = 'STATIC';
        intent = 'GREETING';
        staticResponse = "أهلاً بك! 👋 يسعدنا تواصلك معنا. كيف يمكنني مساعدتك اليوم؟";
    }

    // 4. فحص طلب التحويل البشري (Human Handoff)
    else if (['عملاء', 'موظف', 'بشري', 'انسان', 'تحدث مع', 'support', 'agent', 'human'].some(kw => cleanMessage.includes(kw))) {
        route = 'HANDOFF';
        intent = 'HUMAN_HANDOFF';
        staticResponse = "تم استلام طلبك بنجاح. سيقوم أحد ممثلي خدمة العملاء بالتواصل معك في أقرب وقت.";
    }

    // 5. فحص الرسائل الطويلة جداً
    else if (cleanMessage.length > 1000) {
        route = 'STATIC';
        intent = 'SPAM';
        staticResponse = "الرسالة طويلة جداً، يرجى إرسال استفسارك بشكل مختصر لنتمكن من مساعدتك.";
    }

    return {
        json: {
            phone_number: phone,
            lead_id: leadId,
            original_message: rawMessage,
            route: route,
            intent: intent,
            static_response: staticResponse,
            processed_at: new Date().toISOString()
        }
    };
});

